// @ts-check
/**
 * summary-stage.mjs — Phase 3 generation guards.
 *
 * Two jobs, both about making the generated prose true:
 *
 *   1. The summary is generated by its own call, fed the bullets that will
 *      actually appear on the CV. It used to be one field in a large JSON blob
 *      competing with five other sections, and its repair path
 *      (`reviseSummary`) was built from the JD and the profile narrative and
 *      **never saw the selected bullets at all** — structurally guaranteed to
 *      pull the summary toward the posting. That is the parroting failure mode,
 *      built into the repair.
 *
 *   2. A named product the CV never mentions is stripped, not counted. The
 *      two-tier vocabulary rule — capability phrases free, named products
 *      grounded — is aspirational until violations are actually rejected.
 */

import { parseCvSections, parseEntries, revertUnsupportedBullets } from './cv-select.mjs';

// ── Named-product vocabulary ──────────────────────────────────────────────────
/**
 * A closed vocabulary is deliberate. The alternative — treat any capitalised
 * unknown token as a product — flags every company name, role title and section
 * heading, and a guard that cries wolf gets switched off. This is a *detector*,
 * not a generator: a missing entry understates the count, it never invents one.
 *
 * Seeded from the 9 real violations found across 133 shipped CVs (gcp x3,
 * kotlin, golang, dbt, terraform, azure, angular) and extended to the products a
 * JD in this corpus is likely to name.
 */
export const NAMED_PRODUCTS = [
  // clouds & platforms
  'aws', 'azure', 'gcp', 'google cloud', 'heroku', 'digitalocean', 'cloudflare',
  'firebase', 'vercel', 'netlify', 'openshift', 'cloud foundry',
  // languages
  'kotlin', 'golang', 'scala', 'clojure', 'elixir', 'erlang', 'haskell', 'swift',
  'objective-c', 'perl', 'ruby', 'php', 'c#', 'f#', 'dart', 'julia', 'groovy',
  'visual basic', 'cobol', 'fortran', 'lua', 'r language',
  // frontend
  'angular', 'vue', 'svelte', 'ember', 'backbone', 'jquery', 'solidjs',
  'tailwind', 'bootstrap', 'material ui', 'sass', 'webpack', 'vite', 'nuxt',
  // backend & frameworks
  'django', 'flask', 'fastapi', 'rails', 'laravel', 'symfony', 'phoenix',
  'spring boot', 'quarkus', 'micronaut', 'nestjs', 'gin', 'echo framework',
  'asp.net', '.net core', 'entity framework',
  // data stores
  'cassandra', 'dynamodb', 'cockroachdb', 'couchbase', 'couchdb', 'neo4j',
  'influxdb', 'clickhouse', 'snowflake', 'bigquery', 'redshift', 'databricks',
  'oracle db', 'db2', 'mariadb', 'firestore', 'elasticsearch', 'opensearch',
  'timescaledb', 'scylladb', 'planetscale', 'supabase',
  // streaming & messaging
  'kafka', 'rabbitmq', 'pulsar', 'nats', 'activemq', 'sqs', 'kinesis',
  'flink', 'spark', 'hadoop', 'airflow', 'dagster', 'dbt', 'beam',
  // infra & ops
  'terraform', 'pulumi', 'ansible', 'puppet', 'chef', 'vagrant', 'nomad',
  'consul', 'vault', 'istio', 'linkerd', 'helm', 'argocd', 'flux',
  'cloudformation', 'packer', 'saltstack',
  // observability
  'datadog', 'new relic', 'splunk', 'sentry', 'grafana', 'jaeger', 'zipkin',
  'opentelemetry', 'pagerduty', 'dynatrace', 'appdynamics',
  // ci/cd & vcs
  'circleci', 'travis', 'teamcity', 'bamboo', 'gitlab ci', 'github actions',
  'bitbucket', 'azure devops', 'octopus deploy',
  // ml
  'pytorch', 'tensorflow', 'keras', 'jax', 'scikit-learn', 'huggingface',
  'langchain', 'llamaindex', 'mlflow', 'kubeflow', 'sagemaker', 'vertex ai',
  'weights & biases', 'ray',
  // saas / business
  'salesforce', 'sap', 'workday', 'servicenow', 'netsuite', 'hubspot',
  'shopify', 'magento', 'contentful', 'sanity', 'wordpress', 'drupal',
  'twilio', 'sendgrid', 'auth0', 'okta', 'keycloak', 'segment', 'snowplow',
  'looker', 'tableau', 'power bi', 'qlik', 'metabase', 'superset',
];

/** Normalised text with guaranteed leading/trailing space, for phrase matching. */
function phraseSpace(s) {
  return ` ${String(s || '').toLowerCase().replace(/[^a-z0-9+#.&-]+/g, ' ').replace(/\s+/g, ' ').trim()} `;
}
const hasPhrase = (haystack, phrase) => haystack.includes(` ${phrase} `);

/**
 * Named products the text claims that `cv.md` never mentions.
 * @param {string} text
 * @param {string} cvText
 * @returns {string[]}
 */
export function productFab(text, cvText) {
  const out = phraseSpace(text);
  const cv = phraseSpace(cvText);
  return NAMED_PRODUCTS.filter(p => hasPhrase(out, p) && !hasPhrase(cv, p));
}

/**
 * Drop the clauses that name a product `cv.md` never mentions.
 *
 * Sentence-level, then comma-clause-level: "Built services in Rust, Kotlin and
 * Go" should lose Kotlin, not the whole sentence. Falls back to deleting the
 * sentence only when the clause surgery cannot clear it, because shipping a
 * shorter true summary beats shipping a longer false one.
 *
 * @param {string} text
 * @param {string} cvText
 * @returns {string}
 */
export function stripFabricatedProducts(text, cvText) {
  if (!text) return text;
  if (!productFab(text, cvText).length) return text;

  const sentences = String(text).split(/(?<=[.!?])\s+/);
  const kept = [];
  for (const sentence of sentences) {
    if (!productFab(sentence, cvText).length) { kept.push(sentence); continue; }
    // Try clause surgery before giving up on the whole sentence.
    const clauses = sentence.split(/,\s*/);
    const clean = clauses.filter(c => !productFab(c, cvText).length);
    if (clean.length && clean.length < clauses.length) {
      const rebuilt = clean.join(', ').replace(/\s+and\s*$/i, '').replace(/,\s*$/, '').trim();
      // Only keep the repair if it actually cleared the fabrication — a product
      // sitting in the sentence's only clause survives the join otherwise.
      if (rebuilt && !productFab(rebuilt, cvText).length) {
        kept.push(/[.!?]$/.test(rebuilt) ? rebuilt : `${rebuilt}.`);
      }
    }
  }
  return kept.join(' ').replace(/\s+/g, ' ').trim();
}

/**
 * Revert every experience bullet naming a product `cv.md` never mentions.
 *
 * Bullets get reverted rather than clause-stripped because each one has a known
 * source line in `cv.md` — the untailored truth is right there, and it fills the
 * slot. Summaries and project blurbs have no single source line, so those get
 * `stripFabricatedProducts` instead.
 *
 * @param {any[]} items
 * @param {string} cvText
 */
export function verifyBulletProducts(items, cvText) {
  return revertUnsupportedBullets(items, cvText, b => productFab(b, cvText).length > 0);
}

// ── Summary stage ─────────────────────────────────────────────────────────────

/**
 * The bullets that will actually appear on this CV, in CV order.
 * This is the evidence the summary must describe — not the JD, and not the
 * whole of `cv.md`, but the specific subset `cv-select` chose for this offer.
 * @param {string} selectedCv the post-selection CV handed to the tailor model
 * @returns {string[]}
 */
export function selectedBullets(selectedCv) {
  const out = [];
  try {
    for (const sec of parseCvSections(selectedCv)) {
      if (sec.name !== 'Experience' && sec.name !== 'Projects') continue;
      for (const e of parseEntries(sec.lines).entries) {
        const name = e.head[0].replace(/^###\s+/, '').trim();
        for (const b of e.bullets) out.push(`${name}: ${b}`);
      }
    }
  } catch { /* odd CV shape — caller falls back */ }
  return out;
}

const SUMMARY_SYSTEM = [
  'You write ONE professional summary for a CV. Output ONLY the summary as plain text —',
  'no JSON, no quotes, no preamble, no label.',
  '',
  'Rules:',
  '- Length: 50 to 70 words. Count them. This is mandatory.',
  '- Implied first person: never use a name, never "he"/"she"/"they".',
  '- EVERY claim must be traceable to a specific line of the evidence below. The',
  '  evidence is the ONLY source of fact. You are describing this candidate, not',
  '  the job.',
  '- Do not state a number of years of experience. The evidence does not contain one.',
  '- Do not name a domain or industry the evidence does not show. Do not name a',
  '  technology, product, cloud or framework absent from the evidence. Describing',
  '  the KIND of work ("distributed systems", "low-latency") is fine.',
  '- Never name the target company, and never claim to have worked for them.',
].join('\n');

/**
 * The role title is the only JD-derived input, and even that is only a target.
 *
 * The Block B requirement list used to be passed here as "emphasis context",
 * and the 7B copied it wholesale — for an HFT posting it produced "expertise in
 * networking, HFT, and financial markets" and "over a decade of experience"
 * against a CV showing none of those. Handing a weak model the posting's
 * vocabulary and asking it not to use it does not work.
 *
 * The requirements are also redundant: `cv-select` has already ranked and
 * trimmed these bullets against Block B, so the JD signal is encoded in *which*
 * evidence is here. Describing the evidence faithfully is the tailoring.
 *
 * @param {string[]} bullets the selected CV bullets — the ONLY source of fact
 * @param {string} role
 */
export function summaryUser(bullets, role) {
  const ev = bullets.length ? bullets.map(b => `- ${b}`).join('\n') : '(none)';
  return [
    '## Evidence — the bullets that will appear on this CV',
    '',
    ev,
    '',
    `## Target role title: ${role || 'software engineering'}`,
    '',
    'Write the 50-70 word summary now. Every claim must come from the evidence above.',
  ].join('\n');
}

// ── Code-side candidate scoring ───────────────────────────────────────────────

const CONTENT = /[a-z0-9+#.]{3,}/g;
const contentToks = (s) => new Set((String(s || '').toLowerCase().match(CONTENT) || []));

/**
 * Fraction of the summary's content words that actually appear in the evidence.
 *
 * This is the direct measure of parroting: a summary lifted from the posting
 * scores low here even when it reads well, because the posting's vocabulary is
 * not the CV's. It is the term that stops `summary_jd_fit` being gamed.
 */
export function evidenceOverlap(text, bullets) {
  const t = contentToks(text);
  if (!t.size) return 0;
  const ev = contentToks(bullets.join(' '));
  let n = 0;
  for (const w of t) if (ev.has(w)) n++;
  return n / t.size;
}

// Function words are what separate prose from a keyword dump. Prose runs
// 0.20-0.40 of its tokens here; a slash-separated tag list runs near zero.
const FUNCTION_WORDS = new Set([
  'the', 'and', 'a', 'an', 'of', 'in', 'to', 'for', 'with', 'on', 'at', 'by',
  'from', 'as', 'that', 'this', 'it', 'its', 'into', 'over', 'across', 'where',
  'which', 'while', 'their', 'has', 'have', 'was', 'were', 'been', 'is', 'are',
]);

/**
 * Is this prose at all?
 *
 * Rewarding evidence overlap creates an obvious exploit: a dense list of CV
 * keywords maximises overlap while being unreadable. The stage produced exactly
 * that — "Senior Software Engineer (Graduate) / Production-Grade Backend Systems
 * / SRE-adjacent Operations / 99.9% Uptime ..." — and it scored *well*.
 *
 * So shape is a gate, not a score term: a candidate that is not prose is not a
 * candidate, however well it overlaps.
 */
export function looksLikeProse(text) {
  const words = String(text || '').trim().split(/\s+/).filter(Boolean);
  if (words.length < 20) return false;
  const slashes = (String(text).match(/\//g) || []).length;
  if (slashes >= 3) return false;                       // tag list, not a sentence
  if (!/[.!?]/.test(text)) return false;                // no sentence ever ends
  const fn = words.filter(w => FUNCTION_WORDS.has(w.toLowerCase().replace(/[^a-z]/g, ''))).length;
  return fn / words.length >= 0.12;
}

/**
 * Deterministic quality score for one candidate summary. Higher is better.
 * Label-free: word-count distance, fabricated products, and how much of it is
 * traceable to the evidence. Non-prose scores -Infinity — see looksLikeProse.
 */
export function scoreSummary(text, { bullets, cvText }) {
  if (!text || !looksLikeProse(text)) return -Infinity;
  const w = wordCount(text);
  const lenPenalty = w < 50 ? 50 - w : w > 70 ? w - 70 : 0;
  return -lenPenalty
         - 5 * productFab(text, cvText).length
         + 8 * evidenceOverlap(text, bullets);
}

const wordCount = (s) => String(s || '').trim().split(/\s+/).filter(Boolean).length;

/** Strip the wrappers a model puts around a "plain text only" answer. */
export function cleanSummary(raw) {
  return String(raw || '')
    .trim()
    .replace(/^```[\s\S]*?\n|```$/g, '')
    .replace(/^["'`]+|["'`]+$/g, '')
    .replace(/^(summary|professional summary)\s*[:\-]\s*/i, '')
    .trim();
}

/**
 * Generate the summary from the selected evidence, and return it only if it
 * beats the candidate the main JSON call already produced.
 *
 * Best-of-N by resampling is pointless at the benchmark's temperature 0 — greedy
 * decoding is byte-identical, so N samples are one sample N times. Using the
 * JSON field as the second candidate gives a genuinely different draft for free
 * (it is already generated and paid for) and keeps the whole thing deterministic,
 * which is what makes a single-run A/B valid on this stack.
 *
 * @param {{bullets: string[], role: string, cvText: string, incumbent?: string,
 *          call: (system: string, user: string) => Promise<string>}} opts
 * @returns {Promise<string|null>} the winning summary, or null if neither works
 */
export async function generateSummary({ bullets, role, cvText, incumbent = '', call, margin = 1.0 }) {
  let challenger = null;
  try {
    const text = cleanSummary(await call(SUMMARY_SYSTEM, summaryUser(bullets, role)));
    if (text) challenger = stripFabricatedProducts(text, cvText);
  } catch { /* the incumbent still stands */ }

  const base = incumbent ? stripFabricatedProducts(incumbent, cvText) : null;
  const baseScore = base ? scoreSummary(base, { bullets, cvText }) : -Infinity;
  const chalScore = challenger ? scoreSummary(challenger, { bullets, cvText }) : -Infinity;

  // The incumbent is the shipped behaviour and holds the tie. A new stage only
  // displaces it by a clear margin, never on a rounding difference — measured
  // on offer 182, where the challenger was blander than the JSON field and a
  // bare `>` handed it the slot anyway.
  if (chalScore > baseScore + margin) return challenger;
  return base ?? challenger;
}
